`,y.jsx(t.li,{children:"Location of these pairs are passed back to master node which passes this on to reduce workers"}),`
`,y.jsx(t.li,{children:"Reduce worker uses RPC to read the buffer data from local disk of map workers"}),`
`,y.jsx(t.li,{children:"Once reduce worker reads all data, it sorts these intermediate keys, using external sort if data is too large to fit in memory"}),`
`,y.jsx(t.li,{children:"It iterates over sorted intermediate data, passing each unique key's corresponding set of intermediate values to the reduce function"}),`
`,y.jsx(t.li,{children:"Output is appended to a final output file for this reduce partition"}),`
