`,y.jsxs(t.ul,{children:[`
`,y.jsx(t.li,{children:'A "straggler" is a machine that takes unusually long time to complete one of the last map or reduce tasks'}),`
`,y.jsx(t.li,{children:"Stragglers can occur due to various reasons like bad disks or resource competition"}),`
`,y.jsx(t.li,{children:"When the program is near completion, master schedules backup execution of remaining in-progress tasks"}),`
`,y.jsx(t.li,{children:"Task is marked as complete whenever either primary or backup execution finishes"}),`
